descriptor.templateCss:
.tb-wan-downlink-widget {
  display: grid;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
}

.tb-wan-downlink-target {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}

.tb-wan-downlink-target > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.tb-wan-downlink-target span,
.tb-wan-downlink-error {
  color: rgba(0, 0, 0, 0.6);
  font-size: 12px;
}

.tb-wan-downlink-target strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tb-wan-downlink-error {
  grid-column: 1 / -1;
}

@media (max-width: 480px) {
  .tb-wan-downlink-widget {
    grid-template-columns: minmax(0, 1fr);
  }

  .tb-wan-downlink-widget button {
    width: 100%;
  }
}

descriptor.controllerScript:
let downlinkDialog;

self.onInit = function() {
  self.ctx.ngZone.run(function() {
    const subscription = self.ctx.defaultSubscription;
    const $scope = self.ctx.$scope;
    downlinkDialog = $scope.$injector.get(self.ctx.servicesMap.get('wanDownlinkDialog'));
    $scope.rpcEnabled = subscription.rpcEnabled && !!subscription.targetDeviceId;
    $scope.targetDeviceName = subscription.targetEntityName || self.ctx.translate.instant('device.wan.downlink-widget-no-target');
    $scope.openDownlink = function() {
      if (!$scope.rpcEnabled) {
        return;
      }
      downlinkDialog.open({
        deviceId: subscription.targetDeviceId,
        deviceName: subscription.targetEntityName,
        origin: 'DASHBOARD'
      }).subscribe();
    };
    self.ctx.detectChanges();
  });
};
